"""HTTP client for the Meridian payments API."""

import hashlib
import json
import time
from urllib import request, error as urllib_error


class MeridianClient:
    """HTTP client for the Meridian payments API with pagination, retry, and caching."""

    def __init__(self, base_url: str, api_key: str) -> None:
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self._etag: str | None = None
        self._cached_payments: list[dict] | None = None

    def _headers(self, extra_headers: dict[str, str] | None = None) -> dict[str, str]:
        headers: dict[str, str] = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }
        if self._etag is not None:
            headers["If-None-Match"] = self._etag
        if extra_headers:
            headers.update(extra_headers)
        return headers

    def _request(
        self,
        path: str,
        method: str = "GET",
        body: bytes | None = None,
        extra_headers: dict[str, str] | None = None,
        retries: int = 5,
        backoff_base: float = 0.5,
    ) -> tuple[int, dict[str, str], bytes]:
        url = f"{self.base_url}{path}"
        headers = self._headers(extra_headers)

        attempt = 0
        while attempt < retries:
            try:
                req = request.Request(url, data=body, method=method, headers=headers)
                resp = request.urlopen(req)
                etag = resp.headers.get("ETag") or None
                return resp.status, {"etag": etag} if etag else {}, resp.read()
            except urllib_error.HTTPError as e:
                if e.code == 429 and attempt < retries - 1:
                    retry_after = float(e.headers.get("Retry-After", backoff_base))
                    time.sleep(min(retry_after, 30))
                    attempt += 1
                    continue
                if e.code == 410:
                    self._etag = None
                    self._cached_payments = None
                    raise
                raise

        raise RuntimeError(f"Too many retries for {url}")

    def fetch_all_payments(self) -> list[dict]:
        """Return all payments from the API sorted oldest-first by created_at (UTC), using cursor pagination and ETag caching."""
        # Try cached first (304 Not Modified is handled via If-None-Match).
        try:
            status, resp_headers, raw = self._request("/payments?limit=1")
        except urllib_error.HTTPError as e:
            if e.code == 304 and self._cached_payments is not None:
                return list(self._cached_payments)
            raise

        # If we got a real response, cache is stale or empty.
        all_payments: list[dict] = []
        cursor: str | None = None

        while True:
            parts = ["/payments?limit=100"]
            if cursor is not None:
                parts.append(f"&cursor={cursor}")
            path = "".join(parts)

            try:
                status, resp_headers, raw = self._request(path)
            except urllib_error.HTTPError as e:
                if e.code == 304 and all_payments:
                    return list(self._cached_payments or [])
                raise

            etag = resp_headers.get("etag")
            if etag is not None:
                self._etag = etag

            data = json.loads(raw)
            items = data.get("items", [])
            all_payments.extend(items)

            next_cursor = data.get("next_cursor")
            if not next_cursor:
                break
            cursor = next_cursor

        # Sort oldest-first by created_at (UTC).
        all_payments.sort(key=lambda p: p["created_at"])
        self._cached_payments = all_payments
        return list(all_payments)

    def total_count(self) -> int:
        """Return the total number of payments available in the API collection."""
        try:
            status, _, raw = self._request("/payments/count")
        except urllib_error.HTTPError as e:
            if e.code == 304 and self._cached_payments is not None:
                return len(self._cached_payments)
            raise

        data = json.loads(raw)
        return int(data["count"])

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        """Create a payment and return its id; safe to call repeatedly with the same idempotency_key."""
        payload = json.dumps({
            "amount_minor": amount_minor,
            "currency": currency,
        }).encode("utf-8")

        extra_headers = {"Idempotency-Key": idempotency_key}
        try:
            status, _, raw = self._request(
                "/payments", method="POST", body=payload, extra_headers=extra_headers
            )
        except urllib_error.HTTPError as e:
            if e.code == 409:
                data = json.loads(e.read())
                return str(data["id"])
            raise

        data = json.loads(raw)
        return str(data["id"])
